package lending;

import static readcode.Assert.*;

import java.util.List;

import lending.log.Logger;
import lending.model.LoanApplication;
import lending.service.ApplicationService;
import lending.service.ApplicationService.Decision;

public class LoggingTest {

    private static final String SSN = "529-14-8836";
    private static final String DOB = "1987-03-14";

    private Logger log;
    private ApplicationService service;

    public void setUp() {
        log = Logger.inMemory("applications");
        service = new ApplicationService(log, 5_000_000L);
    }

    private LoanApplication application(String id, long amountCents) {
        return new LoanApplication(id, "Dana Whitfield", SSN, DOB, amountCents);
    }

    private static boolean anyLineContains(List<String> lines, String text) {
        return lines.stream().anyMatch(line -> line.contains(text));
    }

    public void testApprovedApplicationDoesNotLogRawSsn() {
        service.submit(application("app-1", 1_000_000L));
        System.out.println(String.join("\n", log.lines()));
        assertFalse(anyLineContains(log.lines(), SSN), "raw SSN found in logs");
    }

    public void testRejectedApplicationDoesNotLogRawSsn() {
        Decision decision = service.submit(application("app-2", 9_000_000L));
        assertEquals(Decision.REJECTED, decision);
        assertFalse(anyLineContains(log.lines(), SSN), "raw SSN found in the rejection log line");
    }

    public void testDateOfBirthIsNeverLogged() {
        service.submit(application("app-3", 1_000_000L));
        assertFalse(anyLineContains(log.lines(), DOB), "date of birth found in logs");
    }

    public void testLogsStillIdentifyTheApplication() {
        service.submit(application("app-4", 9_000_000L));
        assertTrue(anyLineContains(log.lines(), "app-4"), "application id missing from logs");
        assertTrue(anyLineContains(log.lines(), "9000000"), "amount missing from logs");
    }

    public void testMaskedSsnKeepsLastFourDigits() {
        assertEquals("***-**-8836", application("app-5", 1L).maskedSsn());
        assertEquals("***", new LoanApplication("x", "n", "12", "d", 1L).maskedSsn());
    }

    public void testApprovedApplicationsAreKeptWithFullData() {
        service.submit(application("app-6", 1_000_000L));
        assertEquals(1, service.approved().size());
        assertEquals(SSN, service.approved().get(0).ssn());
    }

    public void testRecordEqualityStillUsesAllFields() {
        assertEquals(application("app-7", 5L), application("app-7", 5L));
        assertFalse(application("app-7", 5L).equals(application("app-7", 6L)), "amounts differ");
    }
}
